solution:
fn copy_data(dest: *Byte, src: *Byte, len: Int)
  requires: dest != null;   // No null destination
  requires: src != null;    // No null source
  requires: len > 0;        // Must copy something
  requires: len <= 1024;    // Bounded copy (prevent overflow)
{
  for i in 0..len {
    dest[i] = src[i];
  }
}

fn main() -> Int {
  let src = [0x41, 0x42, 0x43, 0x44];
  let dest = [0x00, 0x00, 0x00, 0x00];
  copy_data(&dest[0], &src[0], 4);
  return dest[0] as Int;
}
